import pathlib,subprocess,json,hashlib,sys
p=pathlib.Path(sys.argv[1]);commands=[]
def run(args):commands.append(args);return subprocess.check_output(args)
def packets(path):return json.loads(run(['ffprobe','-v','error','-select_streams','v','-show_packets','-show_data_hash','sha256','-of','json',str(path)]))['packets']
a=packets(p/'source.mkv');b=packets(p/'candidate.mp4');assert [q['data_hash'] for q in a]==[q['data_hash'] for q in b];startA=float(a[0]['pts_time']);startB=float(b[0]['pts_time']);maxError=max(abs((float(x['pts_time'])-startA)-(float(y['pts_time'])-startB)) for x,y in zip(a,b));assert maxError<.0011
pcm=run(['ffmpeg','-v','error','-i',str(p/'candidate.mp4'),'-map','0:a:0','-c:a','pcm_s16le','-f','s16le','-']);ref=bytes(json.loads(pathlib.Path('results/top100/lossless/input.json').read_text())['oracle']);assert pcm==ref;(p/'reference.s16').write_bytes(ref);(p/'candidate.s16').write_bytes(pcm);browser=json.loads((p/'results.json').read_text())['probe'];assert browser['originalRejected'] and browser['integerMismatches']==0 and browser['browserFrames']==96000 and browser['closedPartial'] and browser['lifecycle']['eof'] and browser['lifecycle']['seek'] and browser['lifecycle']['rms']>.01
result={'passed':True,'hostPCMBytes':len(pcm),'hostPCMExact':True,'hostPCMSHA256':hashlib.sha256(pcm).hexdigest(),'copiedVideoPackets':len(a),'codedVideoPayloadsExact':True,'normalizedVideoMaxTimeErrorSeconds':maxError,'outputCommonTimestampOrigin':startB,'browserIntegerPCMExact':True,'browserFrames':96000,'partialDecoderJobClosedAndReopened':True,'actualMSESeekEofPassed':True,'limits':['ALAC stereo16/48k synthetic source only','TrueHD/24bit excluded','Two-module finite bridge; no streaming ownership or speed claim','MSE buffered start is1s; owner explicitly starts there, no hidden1s startup audio silence accepted']};(p/'verification.json').write_text(json.dumps(result,indent=2)+'\n');(p/'verification-commands.log').write_text('\n'.join(map(json.dumps,commands))+'\n');print(json.dumps(result))
